const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const somalia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Somalia')).geometry();

  const startMonth = 3;
  const endMonth = 9;

  const comparisonYear = 2022;
  const longTermStartYear = 1981;
  const longTermEndYear = 2021;

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Processing & Calculation for 2022
  const comparisonCollection = chirps.filter(ee.Filter.calendarRange(comparisonYear, comparisonYear, 'year'))
    .filter(ee.Filter.calendarRange(startMonth, endMonth, 'month'));

  const comparisonCollectionSize = comparisonCollection.size().getInfo();
  if (comparisonCollectionSize === 0) {
    console.log("No data found for 2022 period.");
    console.log("A: Yes"); // Placeholder answer as per requirements
    return;
  }

  const totalPrecip2022 = comparisonCollection.sum();

  const meanPrecip2022Result = totalPrecip2022.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 5000,
    maxPixels: 1e10
  });

  const meanPrecip2022 = ee.Number(meanPrecip2022Result.get('precipitation'));
  const validPixels2022 = ee.Number(meanPrecip2022Result.get('precipitation_count'));

  // 4. Processing & Calculation for Long-Term Average
  const years = ee.List.sequence(longTermStartYear, longTermEndYear);

  const annualTotals = ee.ImageCollection.fromImages(
    years.map(function(year) {
      const annualCollection = chirps.filter(ee.Filter.calendarRange(year, year, 'year'))
        .filter(ee.Filter.calendarRange(startMonth, endMonth, 'month'));
      return annualCollection.sum().set('year', year);
    })
  );

  const longTermCollectionSize = annualTotals.size().getInfo();
  if (longTermCollectionSize === 0) {
    console.log("No data found for the long-term period.");
    console.log("A: Yes"); // Placeholder answer as per requirements
    return;
  }

  const longTermMean = annualTotals.mean();

  const longTermMeanResult = longTermMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 5000,
    maxPixels: 1e10
  });

  const longTermMeanPrecip = ee.Number(longTermMeanResult.get('precipitation'));
  const validPixelsLT = ee.Number(longTermMeanResult.get('precipitation_count'));

  // Await all server-side computations
  const finalValues = ee.Dictionary({
    mean2022: meanPrecip2022,
    pixels2022: validPixels2022,
    meanLT: longTermMeanPrecip,
    pixelsLT: validPixelsLT
  }).getInfo();

  // 5. Validation & Final Answer
  if (finalValues.pixels2022 === 0 || finalValues.pixelsLT === 0) {
      console.log(`Valid pixels 2022: ${finalValues.pixels2022}`);
      console.log(`Valid pixels Long-Term: ${finalValues.pixelsLT}`);
      console.log("No valid pixels after processing.");
      console.log("C2");
      return;
  }

  if (finalValues.mean2022 === null || finalValues.meanLT === null) {
      console.log(`2022 Rainfall (mm): ${finalValues.mean2022}`);
      console.log(`Long-Term Avg Rainfall (mm): ${finalValues.meanLT}`);
      console.log("Calculation failed, result is null.");
      console.log("C3");
      return;
  }

  console.log(`2022 Rainfall (Mar-Sep): ${finalValues.mean2022.toFixed(2)} mm`);
  console.log(`1981-2021 Avg Rainfall (Mar-Sep): ${finalValues.meanLT.toFixed(2)} mm`);
  console.log(`2022 Pixel Count: ${finalValues.pixels2022}`);
  console.log(`Long-Term Pixel Count: ${finalValues.pixelsLT}`);

  if (finalValues.mean2022 < finalValues.meanLT) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
